// UI language: zh-TW source strings; zh-CN table generated by i18n/gen_cn.py (OpenCC tw2sp).
// Note: UI language is independent of the video locale (UI_DESIGN.md §8).
import CN from '../i18n/zh-CN.js';

let lang = localStorage.getItem('ui.lang') === 'zh-CN' ? 'zh-CN' : 'zh-TW';
const subs = new Set();

export function getLang() { return lang; }
export function setLang(l, persist = true) {
  lang = l === 'zh-CN' ? 'zh-CN' : 'zh-TW';
  if (persist) localStorage.setItem('ui.lang', lang); // 截圖導覽不保存（WebView 設定檔與使用者的 Studio 共用）
  document.documentElement.lang = lang;
  applyStatic(document);
  subs.forEach((f) => f(lang));
}
export function onLang(f) { subs.add(f); return () => subs.delete(f); }

// t('文字 {n}', {n: 3})
export function t(s, vars) {
  let out = lang === 'zh-CN' ? (CN[s] ?? s) : s;
  if (vars) out = out.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m));
  return out;
}

// static markup: data-i18n (textContent), data-i18n-title, data-i18n-aria, data-i18n-ph
export function applyStatic(root) {
  root.querySelectorAll('[data-i18n]').forEach((el) => { el.textContent = t(el.dataset.i18n); });
  root.querySelectorAll('[data-i18n-title]').forEach((el) => { el.title = t(el.dataset.i18nTitle); });
  root.querySelectorAll('[data-i18n-aria]').forEach((el) => { el.setAttribute('aria-label', t(el.dataset.i18nAria)); });
  root.querySelectorAll('[data-i18n-ph]').forEach((el) => { el.placeholder = t(el.dataset.i18nPh); });
}

document.documentElement.lang = lang;
